/**
 * 对对象数组按年龄（age）升序排序，不修改原数组。
 * @param {Array<Object>} arr - 包含对象的数组，每个对象需有 'age' 属性。
 * @returns {Array<Object>} 一个新的、已排序的数组。
 */
function sortByAgeAscending(arr) {
    // 1. 使用 slice() 创建原数组的浅拷贝，确保不修改原数组
    const newArr = arr.slice();

    // 2. 使用 sort() 方法进行排序
    // 比较函数 (a, b) => a.age - b.age：
    // 如果结果为负，a排在b前面（升序）；如果为正，a排在b后面。
    newArr.sort((a, b) => a.age - b.age);

    // 3. 返回新的排序数组
    return newArr;
